# owner: platform
import unittest

from hourglass.rounding import (
    round_span,
    rounded_labels,
    snap,
    span_label,
)
from hourglass.models import Span


class SnapTests(unittest.TestCase):
    def test_nearest_step(self):
        self.assertEqual(snap(542, 15), 540)
        self.assertEqual(snap(548, 15), 555)

    def test_halves_go_up(self):
        self.assertEqual(snap(15, 30), 30)
        self.assertEqual(snap(5, 10), 10)


class LabelTests(unittest.TestCase):
    def test_label(self):
        span = Span(540, 1035)
        self.assertEqual(
            span_label(span), "09:00-17:15 (8h 15m)"
        )

    def test_rounds_each_span(self):
        spans = [Span(541, 1033), Span(1100, 1200)]
        self.assertEqual(
            rounded_labels(spans, 15),
            [
                "09:00-17:15 (8h 15m)",
                "18:15-20:00 (1h 45m)",
            ],
        )

    def test_end_of_day(self):
        self.assertEqual(
            rounded_labels([Span(1400, 1440)], 30),
            ["23:30-24:00 (0h 30m)"],
        )

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 15), [])


class BadStepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                rounded_labels([Span(0, 60)], step)

    def test_bad_step_raises_for_empty(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(500, 502), 15)
